"""Run lookup and opening run folders."""

import json
import os
from collections.abc import Sequence
from dataclasses import dataclass
from datetime import UTC, datetime
from pathlib import Path
from typing import Any, Literal

import torch

from rllab.core import (
    ActionSpace,
    Box,
    Discrete,
    EpisodeResult,
    MeasureSpec,
    MethodConfig,
    RunConfig,
    TeamSpec,
    WorldSpec,
)
from rllab.runlog.types import Checkpoint, EvalPoint, Failure, Run, RunRecord, RunStatus

_STATUSES: dict[str, RunStatus] = {
    "running": "running",
    "finished": "finished",
    "incomplete": "incomplete",
    "failed": "failed",
}
_METHODS: dict[str, Literal["dqn", "ppo"]] = {"dqn": "dqn", "ppo": "ppo"}
_DIRECTIONS: dict[str, Literal["higher", "lower"]] = {"higher": "higher", "lower": "lower"}


@dataclass(frozen=True)
class FolderRun:
    """A run folder read from disk; the logs and checkpoints are re-read on each call (LOG-06)."""

    record: RunRecord

    def episodes(self) -> list[EpisodeResult]:
        return [EpisodeResult(**line) for line in _lines(self.record.path / "episodes.jsonl")]

    def evals(self) -> list[EvalPoint]:
        return [EvalPoint(**line) for line in _lines(self.record.path / "evals.jsonl")]

    def checkpoints(self) -> list[Checkpoint]:
        paths = (self.record.path / "checkpoints").glob("ckpt_*.pt")
        return sorted((_checkpoint(p) for p in paths), key=lambda c: c.pct)


def find_runs(root: Path, world: str, variant: str, *, include: Sequence[str] = ()) -> list[Run]:
    """The finished runs under `root/<world>/<variant>/`, plus the other runs named in `include`."""
    opened = [open_run(p.parent) for p in sorted((root / world / variant).glob("*/run.json"))]
    return [r for r in opened if r.record.status == "finished" or r.record.config.name in include]


def open_run(path: Path) -> Run:
    """The run folder at `path`, whatever its status; `FileNotFoundError` without a `run.json`."""
    record_file = path / "run.json"
    if not record_file.is_file():
        raise FileNotFoundError(f"no run.json at {path}")
    return FolderRun(_record(path, json.loads(record_file.read_text())))


def _record(path: Path, data: dict[str, Any]) -> RunRecord:
    """`run.json` as a record. A hand-written one may leave out the spec, the start time, the
    method settings or the path: the folder itself stands in for the path, its `run.json` time
    for the start and its config's world, variant and teams for the spec."""
    config = _config(data["config"])
    started = data.get("started")
    ended = data.get("ended")
    failure = data.get("failure")
    return RunRecord(
        config=config,
        spec=_spec(data["spec"]) if "spec" in data else _bare_spec(config),
        started=_time(started) if started else _modified(path / "run.json"),
        ended=_time(ended) if ended else None,
        status=_status(data["status"], data.get("pid")),
        failure=Failure(failure["step"], failure["value"], Path(failure["checkpoint"]))
        if failure
        else None,
        path=path,
    )


def _status(status: str, pid: int | None) -> RunStatus:
    """A `running` run whose writing process (`pid` in `run.json`) is gone reads as incomplete."""
    if status == "running" and not (pid is not None and _alive(pid)):
        return "incomplete"
    return _STATUSES[status]


def _alive(pid: int) -> bool:
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    return True


def _config(data: dict[str, Any]) -> RunConfig:
    return RunConfig(
        name=data["name"],
        world=data["world"],
        variant=data["variant"],
        methods=_methods(data.get("methods", {})),
        seed=data["seed"],
        budget=data["budget"],
        check_settings=data.get("check_settings", {}),
        device=data.get("device", "cpu"),
    )


def _methods(data: dict[str, Any]) -> dict[str, MethodConfig]:
    return {
        team: MethodConfig(_METHODS[m["method"]], m.get("settings", {})) for team, m in data.items()
    }


def _spec(data: dict[str, Any]) -> WorldSpec:
    return WorldSpec(
        world=data["world"],
        variant=data["variant"],
        agents=tuple(data["agents"]),
        teams=tuple(_team(t) for t in data["teams"]),
        obs_len=data["obs_len"],
        action=_action(data["action"]),
        max_steps=data["max_steps"],
        measures=tuple(
            MeasureSpec(m["name"], m["team"], _DIRECTIONS[m["direction"]])
            for m in data["measures"]
        ),
        sight=data["sight"],
    )


def _bare_spec(config: RunConfig) -> WorldSpec:
    """The spec of a hand-written `run.json` without one: its world, variant and teams only."""
    teams = tuple(TeamSpec(team, (), team, "higher") for team in config.methods)
    return WorldSpec(config.world, config.variant, (), teams, 0, Discrete(0), 0, (), None)


def _team(data: dict[str, Any]) -> TeamSpec:
    direction = _DIRECTIONS[data["direction"]]
    return TeamSpec(data["name"], tuple(data["agents"]), data["score_name"], direction)


def _action(data: dict[str, Any]) -> ActionSpace:
    if "n" in data:
        return Discrete(data["n"])
    return Box(data["dims"], data["low"], data["high"])


def _checkpoint(path: Path) -> Checkpoint:
    saved = torch.load(path, weights_only=True)
    return Checkpoint(
        run=saved["run"],
        pct=saved["pct"],
        step=saved["step"],
        spec=_spec(saved["spec"]),
        methods=_methods(saved["methods"]),
        state=saved["state"],
        path=path,
    )


def _lines(path: Path) -> list[dict[str, Any]]:
    """The complete lines of a JSON Lines log; a line still being written is left out."""
    if not path.is_file():
        return []
    *complete, _partial = path.read_text().split("\n")
    return [json.loads(line) for line in complete if line]


def _time(text: str) -> datetime:
    return datetime.fromisoformat(text)


def _modified(path: Path) -> datetime:
    return datetime.fromtimestamp(path.stat().st_mtime, UTC)

